        "evidence_in_work": "ROW_NUMBER() OVER (PARTITION BY {pkpart} ORDER BY {pkpart}) AS _row_num; FROM validated_rows WHERE _row_num = 1",
        "source": "created_at <= CURRENT_TIMESTAMP; created_at >= '2000-01-01'; on_failure: delete_row",
        "importance": 3,
        "reason": "Losing a valid candidate also removes its applications from downstream inner joins."
      },
      {
        "problem": "Conflicting duplicate candidate profiles are resolved arbitrarily rather than using a checked version-selection policy.",
        "about": "data",
        "evidence_in_work": "ROW_NUMBER() OVER (PARTITION BY {pkpart} ORDER BY {pkpart})",
        "source": "primary_key: [\"candidate_id\"]",
        "importance": 2,
        "reason": "If duplicate identifiers have different profile values, downstream names, companies, and contact information can vary between executions."
      }
    ],
    "fewer_reason": "No additional concrete candidate-specific discrepancies are supported by the visible work."
  },
